import { FlowArray } from '@servicenow/sdk/automation'
import { BooleanColumn, ChoiceColumn, StringColumn } from '@servicenow/sdk/core'
import { ActionDefinition } from '@servicenow/sdk/automation'

// Action 1: Create User Account in Active Directory
export const createADUserAccount = ActionDefinition({
    $id: Now.ID['ad_create_user'],
    name: 'Create AD User',
    category: 'HR Onboarding',
    annotation: 'Creates a new Active Directory user account',
    inputs: {
        username: StringColumn({ label: 'Username', mandatory: true }),
        roles: FlowArray({
            label: 'Roles',
            mandatory: true,
            elementType: StringColumn({ mandatory: true, label: 'roles_child0_label' }),
            childName: 'role_child0',
        }),
    },
    outputs: {
        userId: StringColumn({ label: 'User ID', mandatory: true }),
        success: BooleanColumn({ label: 'Success', mandatory: true }),
    },
})

// Action 2: Provision Laptop and Accessories
export const provisionDevice = ActionDefinition({
    $id: Now.ID['provision_device'],
    name: 'Provision Device',
    category: 'HR Onboarding',
    annotation: 'Provisions a laptop/desktop/tablet and accessories',
    inputs: {
        deviceType: ChoiceColumn({
            label: 'Device Type',
            mandatory: true,
            choices: {
                Laptop: { label: 'Laptop' },
                Desktop: { label: 'Desktop' },
                Tablet: { label: 'Tablet' },
            },
            default: 'Laptop',
        }),
        accessoryList: FlowArray({
            label: 'Accessory List',
            mandatory: false,
            elementType: StringColumn({ mandatory: false, label: 'accessorylist_child0_label' }),
            childName: 'accessory_child0',
        }),
    },
    outputs: {
        provisioningStatus: StringColumn({ label: 'Status', mandatory: true }),
    },
})
